#!/bin/sh
# hexn_morse_build_v1.sh -- open-flow build of the Morse-key demo (hexn_morse_top_v1) for the Tang Nano 20K (new file 1 Nov 2026): yosys synth_gowin -> YoWASP nextpnr-himbaechel -> gowin_pack. NOT run on a board.
# Usage: sh tools/hexn_morse_build_v1.sh   Output: fpga/build/hexn_morse_demo_v1/ (unit_top.cst, unit_top.fs, report json)
cd "$(dirname "$0")/.." || exit 1; R=$(pwd); O=$R/fpga/build/hexn_morse_demo_v1; rm -rf $O; mkdir -p $O; python3 tools/hexn_morse_gen_v1.py > /dev/null || exit 1; cd $O || exit 1
python3 - <<'PY'
pins = {"BOARD_CLK": 4, "KEY_S1": 88, "BTN1_N": 72, "BTN2_N": 71, "DISP_LATCH": 25, "DISP_CLK": 26, "DISP_DATA": 27, "BUZZER": 28,
        "LED_N[0]": 15, "LED_N[1]": 16, "LED_N[2]": 17, "LED_N[3]": 18, "LED_N[4]": 19, "LED_N[5]": 20}
L = ["// GENERATED by tools/hexn_morse_build_v1.sh -- pins as in docs/hex-n/DEMO_MORSE_v1.md (shield A1 72 = key, A2 71 = clear, display 25/26/27, buzzer 28). NOT checked on a board."]
for n, p in pins.items():
    L.append('IO_LOC "%s" %d;' % (n, p))
    L.append('IO_PORT "%s" IO_TYPE=LVCMOS33 %s;' % (n, "PULL_MODE=NONE" if n in ("BOARD_CLK", "KEY_S1") else "PULL_MODE=UP" if n.startswith("BTN") else "DRIVE=8"))
open("unit_top.cst", "w").write("\n".join(L) + "\n")
PY
V=$R/fpga/verilog
yosys -q -l synth.log -p "read_verilog -sv $V/hexn_morse_top_v1.v $V/hexn_morse_gen_v1.v $V/hexn_scorer_v1.v $V/hw262_shield_v2.v; synth_gowin -top hexn_morse_top_v1 -json t.json" > synth.out 2>&1 || { echo "synthesis failed"; tail -8 synth.out; exit 1; }
yowasp-nextpnr-himbaechel-gowin --device GW2AR-LV18QN88C8/I7 --vopt family=GW2A-18C --vopt cst=unit_top.cst --json t.json --freq 27 --seed ${SEED:-1} --report unit_top_report.json --write routed.json > pnr.log 2>&1 || { echo "place and route failed"; tail -15 pnr.log; exit 1; }
gowin_pack -d GW2A-18C -o unit_top.fs routed.json > pack.log 2>&1 || { echo "pack failed"; tail -5 pack.log; exit 1; }
python3 - <<'PY'
import json; r = json.load(open("unit_top_report.json")); u = r.get("utilization", {})
print({k: "%s/%s" % (v["used"], v["available"]) for k, v in u.items() if v.get("used")}); print("clock:", {k: (v["achieved"], v["constraint"]) for k, v in r.get("fmax", {}).items()}, "MHz achieved (target)")
PY
rm -f t.json routed.json synth.out pack.log pnr.log synth.log; ls -l unit_top.fs
